class Program {
    static void adjust(int limit, int[] values) {
        limit = 9;
        values[0] += 2;
        values = new int[] {99};
    }
    public static void main(String[] args) {
        int limit = 3;
        int[] values = {5};
        adjust(limit, values);
        System.out.println(limit + " " + values[0]);
    }
}

class Program {
    static class Meter {
        private int units;
        private static int created;
        Meter(int units) { this.units = units; created++; }
        void add(int extra) { units += extra; }
        int units() { return units; }
        static int created() { return created; }
    }
    public static void main(String[] args) {
        Meter first = new Meter(10);
        Meter second = new Meter(20);
        Meter alias = first;
        alias.add(3);
        System.out.println(first.units() + " " + second.units()
                + " " + Meter.created());
    }
}

class Program {
    static int prefixSum(int[] values, int length) {
        if (length == 0) return 0;
        return values[length - 1] + prefixSum(values, length - 1);
    }
    public static void main(String[] args) {
        int[] a = {2, 4, 6};
        int[] b = a;
        b[1] = 9;
        int[] c = a.clone();
        c[0] = 8;
        System.out.println(a[0] + " " + a[1] + " " + c[0]);
        System.out.println(prefixSum(a, a.length));
    }
}

class Program {
    static class IntList {
        private final int[] data = new int[3];
        private int size;
        boolean add(int value) {
            if (size == data.length) return false;
            data[size++] = value;
            return true;
        }
        boolean removeFirst(int value) {
            int i = 0;
            while (i < size && data[i] != value) i++;
            if (i == size) return false;
            for (int j = i; j < size - 1; j++) data[j] = data[j + 1];
            data[--size] = 0;
            return true;
        }
        String contents() {
            return java.util.Arrays.toString(java.util.Arrays.copyOf(data, size));
        }
    }
    public static void main(String[] args) {
        IntList values = new IntList();
        values.add(4); values.add(7); values.add(4);
        System.out.println(values.add(9));
        values.removeFirst(4);
        System.out.println(values.contents());
    }
}

